package com.dentalcrm.common;
import com.dentalcrm.user.UserRepository; import org.springframework.context.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
@Configuration @EnableMethodSecurity
public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService userDetailsService(UserRepository repository){return username->{var u=repository.findByUsernameIgnoreCase(username).orElseThrow(()->new UsernameNotFoundException("Invalid credentials"));return org.springframework.security.core.userdetails.User.withUsername(u.getUsername()).password(u.getPasswordHash()).roles(u.getRole().name()).disabled(!u.isActive()).build();};}
 @Bean SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {return http.csrf(csrf->csrf.csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse()).ignoringRequestMatchers("/api/auth/login")).formLogin(f->f.disable()).httpBasic(b->b.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/auth/csrf").permitAll().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((req,res,ex)->res.sendError(HttpStatus.UNAUTHORIZED.value())).accessDeniedHandler((req,res,ex)->res.sendError(HttpStatus.FORBIDDEN.value()))).build();}
}
